import json
with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].rsplit('/',1)[-1].rsplit('\\\\',1)[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg.get('resolvedVersion', pkg.get('requestedVersion','?'))
        result[name] = pkgs
    return result

b = extract(baseline)
a = extract(after)
print('BASELINE:')
for p in sorted(b): 
    for pkg in sorted(b[p]): print(f'  {p}: {pkg} = {b[p][pkg]}')
print('AFTER:')
for p in sorted(a):
    for pkg in sorted(a[p]): print(f'  {p}: {pkg} = {a[p][pkg]}')
print('CHANGES:')
for p in sorted(set(list(b.keys())+list(a.keys()))):
    bp = b.get(p,{})
    ap = a.get(p,{})
    for pkg in sorted(set(list(bp.keys())+list(ap.keys()))):
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av: print(f'  {p}: {pkg} {bv} -> {av}')
"

